using NCICParser.Models;

namespace NCICParser.Interfaces;

/// <summary>
/// Parses the NCIC Code Manual text generated by
/// Poppler's pdftotext utility.
///
/// The parser discovers section sections, subsections,
/// column definitions, category-list relationships,
/// and code rows before performing several
/// normalization passes.
/// </summary>
public interface IParser
{
    /// <summary>
    /// Entry point for parsing the text file containing the known
    /// NCIC codes
    /// </summary>
    /// <param name="filePath">Full file path to the NCIC text file (including extension)</param>
    /// <returns>List of parsed Sections containing all parsed content</returns>
    List<Section> Parse(string filePath, string dateEoPText);
}
